mapper.select:
SELECT a.*, u_passwd as passwd
FROM t_user a
WHERE u_id = #{userid}

mapper.update:
UPDATE t_user 
SET u_login_dt = datetime('now', 'localtime'), u_err_dt = NULL, u_err_cnt = 0, u_status = 'A' 
WHERE u_id = #{userid}

UPDATE t_user 
SET u_err_dt = datetime('now', 'localtime'), u_err_cnt = u_err_cnt + 1, u_status = CASE WHEN u_err_cnt >= 5 THEN 'B' ELSE 'A' END 
WHERE u_id = #{userid}

mapper.select:
SELECT *, (SELECT sc_name FROM t_system_code WHERE sc_cd = u_auth AND sc_pcd = '0002') u_auth_nm, (SELECT sc_name FROM t_system_code WHERE sc_cd = u_status AND sc_pcd = '0001') u_status_nm FROM t_user
ORDER BY u_enr_dt DESC
LIMIT ${ViewRow} OFFSET ${limit}

